    private static ByteBuffer putInt16(int v) {
        ByteBuffer buf = ByteBuffer.allocate(2);
        buf.put((byte) ((v >> 8) & 0xFF));
        buf.put((byte) (v & 0xFF));
        buf.flip();
        return buf;
    }

    // helper to create a simple 2-byte integer followed by zero padding
    // returns a buffer ready to read, but we will slice as needed.
    private static ByteBuffer wrap2(int v) {
