        dataSize.put((byte) 0x00);
        dataSize.put((byte) 0x02);
        dataSize.flip();

        // Send body chunk prefix
        ByteBuffer prefix = ByteBuffer.allocate(1);
        prefix.put((byte) AjpConstants.FRAME_TYPE_SEND_BODY_CHUNK);
        prefix.flip();

        // body chunk length: 1
        ByteBuffer chunkLen = putInt16(1);

        // Append to a single buffer for simplicity
        ByteBuffer combined = ByteBuffer.allocate(2 + 2 + 1 + 2);
        combined.put(magic.get());
        combined.put(dataSize.get());
        combined.put(prefix.get());
        combined.put(chunkLen.get());
        combined.flip();

        assertDoesNotThrow(() -> p.parse(combined));
