import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class AjpResponseParserParseTests {

    @Test
    void wrongMagicNumberThrows(IOException) throws IOException {
        // Prepare a buffer with a wrong magic number (not 'AB')
        ByteBuffer buf = ByteBuffer.allocate(2);
        buf.put((byte) 'X');
        buf.put((byte) 'Y');
        buf.flip();

        AjpResponseParser parser = new AjpResponseParser();
        assertThrows(IOException.class, () -> parser.parse(buf));
    }

    @Test
    void unknownPrefixImmediatelyCompletesParse() throws IOException {
        // Sequence: AB magic, 2-byte data size, unknown prefix
        // AB = "A","B"; data size = 0x0000 (ignored for this test); prefix = 0x01 (unknown)
        ByteBuffer buf = ByteBuffer.allocate(5);
        buf.put((byte) 'A').put((byte) 'B');
        buf.put((byte) 0x00).put((byte) 0x00);
        buf.put((byte) 0x01); // unknown prefix
        buf.flip();

        AjpResponseParser parser = new AjpResponseParser();
        parser.parse(buf);

        // The parser should transition to DONE when an unknown prefix is encountered
        assertTrue(parser.isComplete(), "Parser should be DONE after encountering unknown prefix");
    }

