    void endResponseIncludesPersistentBooleanAndCompletes() throws IOException {
        // Sequence: AB magic, 2-byte data size, END_RESPONSE, 1-byte boolean
        // END_RESPONSE
        // This should transition to READING_PERSISTENT_BOOLEAN and then to DONE after the boolean byte is read
        ByteBuffer buf = ByteBuffer.allocate(6);
        buf.put((byte) 'A').put((byte) 'B');
        buf.put((byte) 0x00).put((byte) 0x00);
        // END_RESPONSE
        buf.put((byte) io.undertow.protocols.ajp.AjpConstants.FRAME_TYPE_END_RESPONSE);
        // boolean value (e.g., 1)
        buf.put((byte) 0x01);
        buf.flip();

