package io.undertow.protocols.ajp;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;
import java.util.HashSet;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

public class AjpResponseParserParseTests {

    private static int getIntConstant(String name) {
        try {
            Field f = AjpResponseParser.class.getDeclaredField(name);
            f.setAccessible(true);
            return f.getInt(null);
        } catch (Exception e) {
            throw new RuntimeException("Failed to read constant " + name, e);
        }
    }

    @Test
    void testWrongMagicNumberThrowsIOException() {
        int ab = getIntConstant("AB");
        int wrong = ab ^ 0xFFFF; // ensure different value

        ByteBuffer buf = ByteBuffer.allocate(6);
        buf.putShort((short) wrong); // wrong magic
        buf.putShort((short) 0);     // data size = 0 (no further data)
        buf.flip();

        IOException ex = assertThrows(IOException.class, () -> AjpResponseParser.INSTANCE.parse(buf));
        assertEquals("Wrong magic number", ex.getMessage());
    }

    @Test
    void testParseEndToEndCompletesAndConsumesAllBytes() {
        int ab = getIntConstant("AB");
        int endResp = getIntConstant("FRAME_TYPE_END_RESPONSE");

        ByteBuffer buf = ByteBuffer.allocate(6);
        buf.putShort((short) ab);         // AB
        buf.putShort((short) 0);          // data size = 0
        buf.put((byte) endResp);          // prefix END_RESPONSE
        buf.put((byte) 0x01);             // persistent boolean / body chunk size
        buf.flip();

        assertDoesNotThrow(() -> AjpResponseParser.INSTANCE.parse(buf));
        assertEquals(0, buf.remaining(), "Buffer should be fully consumed by a complete parse sequence");
    }

    @Test
    void testInvalidPrefixLeavesBytesRemaining() {
        int ab = getIntConstant("AB");
        int endResp = getIntConstant("FRAME_TYPE_END_RESPONSE");
        int sendHeaders = getIntConstant("FRAME_TYPE_SEND_HEADERS");
        int reqBodyChunk = getIntConstant("FRAME_TYPE_REQUEST_BODY_CHUNK");

        // Choose a prefix that's not among the valid ones
        Set<Integer> allowed = new HashSet<>();
        allowed.add(endResp);
        allowed.add(sendHeaders);
        allowed.add(reqBodyChunk);

        int invalidPrefix = 0;
        while (allowed.contains(invalidPrefix) || invalidPrefix < 0 || invalidPrefix > 0xFF) {
            invalidPrefix++;
        }

        ByteBuffer buf = ByteBuffer.allocate(6);
        buf.putShort((short) ab);          // AB
        buf.putShort((short) 0);           // data size = 0
        buf.put((byte) invalidPrefix);     // invalid prefix
        buf.put((byte) 0xFF);              // tail byte to verify it's not consumed
        buf.flip();

        // Should parse without throwing, but leave the tail byte unconsumed
        assertDoesNotThrow(() -> AjpResponseParser.INSTANCE.parse(buf));
        assertEquals(1, buf.remaining(), "One byte tail should remain unconsumed after invalid prefix");
    }
}

