package io.undertow.protocols.ajp;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.*;
import io.undertow.util.HeaderMap;

public class AjpResponseParserParseTests {

    /**
     * Ensure that invoking parse with an empty buffer does not alter the parser's state.
     * This exercises the early exit in parse when there is no data to read.
     */
    @Test
    public void testParseWithEmptyBufferLeavesStateUnchanged() {
        AjpResponseParser parser = AjpResponseParser.INSTANCE;
        // Put the parser into a known state that is not the initial BEGIN to avoid magic-number path.
        parser.state = AjpResponseParser.READING_PREFIX_CODE;
        parser.prefix = 0;
        parser.readHeaders = 0;
        parser.numHeaders = 0;
        parser.statusCode = 0;
        parser.reasonPhrase = null;
        parser.headers = new HeaderMap();

        ByteBuffer empty = ByteBuffer.allocate(0);

        try {
            parser.parse(empty);
        } catch (IOException e) {
            fail("No exception should be thrown for empty buffer: " + e.getMessage());
        }

        // State should remain as we had set it
        assertEquals(AjpResponseParser.READING_PREFIX_CODE, parser.state, "Parser state should remain unchanged after empty input");
    }

    /**
     * Verify that when the parser is in READING_NUM_HEADERS and a zero header count is read,
     * the parser transitions to DONE (through the fall-through into READING_HEADERS).
     * This tests a complete minimal headers block (0 headers) path.
     */
    @Test
    public void testParseZeroHeadersTransitionsToDone() {
        AjpResponseParser parser = AjpResponseParser.INSTANCE;
        // Prepare parser to read the number of headers
        parser.state = AjpResponseParser.READING_NUM_HEADERS;
        parser.readHeaders = 0;
        parser.numHeaders = 0;

        // Two-byte 0 value for number of headers
        ByteBuffer buf = ByteBuffer.allocate(2);
        buf.put((byte)0);
        buf.put((byte)0);
        buf.flip();

        try {
            parser.parse(buf);
        } catch (IOException e) {
            fail("Unexpected IOException: " + e.getMessage());
        }

        // After processing 0 headers, the parser should be DONE
        assertEquals(AjpResponseParser.DONE, parser.state, "Parser should be DONE after processing zero headers");
        assertEquals(0, parser.numHeaders, "Number of headers should remain zero");
    }

    /**
     * Ensure that if the data for the next numeric value is incomplete (only a single byte),
     * the parser preserves the current state and does not advance.
     */
    @Test
    public void testParsePartialHeaderCountKeepsState() {
        AjpResponseParser parser = AjpResponseParser.INSTANCE;
        parser.state = AjpResponseParser.READING_NUM_HEADERS;
        parser.readHeaders = 0;
        parser.numHeaders = 0;

        // Only a single byte when two are required
        ByteBuffer buf = ByteBuffer.allocate(1);
        buf.put((byte)1);
        buf.flip();

        try {
            parser.parse(buf);
        } catch (IOException e) {
            fail("No exception should be thrown on partial input: " + e.getMessage());
        }

        // State should remain READING_NUM_HEADERS due to incomplete read
        assertEquals(AjpResponseParser.READING_NUM_HEADERS, parser.state, "Parser should remain in READING_NUM_HEADERS on partial data");
        // numHeaders should not have been updated due to incomplete read
        assertEquals(0, parser.numHeaders, "numHeaders should remain unchanged on partial read");
    }
}

