    // Helper: create a simple HeaderMap with given header name and values
    private HeaderMap createHeaders(String name, String... values) {
        HeaderMap map = new HeaderMap();
        HttpString headerName = HttpString.tryFromString(name);
        if (headerName == null) {
            headerName = new HttpString(name);
        }
        for (String v : values) {
            map.add(headerName, v);
        }
        // add() delegates to internal header map builder; we mimic adding by existing API
        return map;
    }

    // Helper: ensure a buffer holds expected data length and that complete flag is returned
    private void assertCompleteState(HpackEncoder encoder, HeaderMap headers, ByteBuffer target) {
        HpackEncoder.State s = encoder.encode(headers, target);
        assertEquals(HpackEncoder.State.COMPLETE, s);
    }

    // Basic test: encoding a single simple header without overflow
    @Test
    void testEncodeSingleHeaderNoOverflow() {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap headers = new HeaderMap();
        HttpString name = HttpString.tryFromString(":method");
        if (name == null) name = new HttpString(":method");
        headers.add(name, "GET");

        ByteBuffer buf = ByteBuffer.allocate(1024);
        HpackEncoder.State state = encoder.encode(headers, buf);

        // Expect COMPLETE and some bytes written
        assertEquals(HpackEncoder.State.COMPLETE, state);
        assertTrue(buf.position() > 0, "Buffer should contain encoded header data");
    }

    // Test overflow behavior: ensure that when target buffer is too small, OVERFLOW is returned
    @Test
    void testOverflowWhenBufferTooSmall() {
        HpackEncoder encoder = new HpackEncoder(32); // intentionally tiny dynamic table size to create larger encoding
        HeaderMap headers = new HeaderMap();
        headers.add(HttpString.tryFromString(":method"), "GET");
        headers.add(HttpString.tryFromString("content-length"), "1234");

