        ByteBuffer target = ByteBuffer.allocate(4);
        HpackEncoder.State state = encoder.encode(headers, target);
        assertEquals(HpackEncoder.State.OVERFLOW, state, "Expected OVERFLOW when target buffer is too small");
    }

