        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap first = new HeaderMap();
        first.add(HttpString.tryFromString(":method"), "GET");

        ByteBuffer target1 = ByteBuffer.allocate(64);
        // First call fills for demonstration; we expect OVERFLOW only if buffer too small
        HpackEncoder.State s = encoder.encode(first, target1);
        // Regardless of first result, ensure subsequent continuation with a different map fails
        HeaderMap second = new HeaderMap();
        second.add(HttpString.tryFromString(":path"), "/index.html");

        // After an initial encode, using a different HeaderMap instance should throw
        // as per spec/implementation (IllegalStateException)
        assertThrows(IllegalStateException.class, () -> encoder.encode(second, ByteBuffer.allocate(64)));
    }

