    @Test
    void testHandleTableSizeChangeSignaling() {
        HpackEncoder encoder = new HpackEncoder(256);
        encoder.setMaxTableSize(128); // request a new max table size
        HeaderMap headers = new HeaderMap();
        headers.add(HttpString.tryFromString(":method"), "GET");
