        // First call should emit new max table size signal among the data
        HpackEncoder.State state = encoder.encode(headers, target);
        // The exact bytes vary, but ensure we complete without exception and produced data
        assertNotNull(state);
        assertTrue(target.position() > 0 || state == HpackEncoder.State.OVERFLOW);
    }

    // Positive flow: ensure that the encoder can complete when enough space is provided
    @Test
    void testCompleteFlowWithMultipleHeaders() {
        HpackEncoder encoder = new HpackEncoder(1024);
        HeaderMap headers = new HeaderMap();
        headers.add(HttpString.tryFromString(":method"), "GET");
        headers.add(HttpString.tryFromString("content-type"), "text/html");
        headers.add(HttpString.tryFromString("custom-header"), "custom-value");

        ByteBuffer target = ByteBuffer.allocate(2048);
        HpackEncoder.State state = encoder.encode(headers, target);
        assertEquals(HpackEncoder.State.COMPLETE, state);
        assertTrue(target.position() > 0, "Encoded data should be written to the buffer");
    }

}

