     * and ensure the encoder reports COMPLETE and writes non-empty data.
     */
    @Test
    public void testEncodeSimpleHeadersCompletesWithoutOverflow() {
        HpackEncoder encoder = new HpackEncoder(4096);
        HeaderMap headers = new HeaderMap();
        headers.put(Headers.CONTENT_TYPE, "text/plain");
        headers.put(Headers.DATE, "Mon, 01 Jan 2024 00:00:00 GMT");

        ByteBuffer buffer = ByteBuffer.allocate(512);

        HpackEncoder.State result = encoder.encode(headers, buffer);
        assertEquals(HpackEncoder.State.COMPLETE, result, "Expected COMPLETE when buffer is large enough for simple headers");
        assertTrue(buffer.position() > 0, "Buffer should contain encoded data");
    }

    /**
     * Overflow behavior: force the encoder to overflow by providing a tiny target buffer,
     * ensure it returns OVERFLOW and that overflowData is populated for continuation.
     */
    @Test
    public void testEncodeOverflowProducesOverflowStateAndOverflowBuffer() {
        HpackEncoder encoder = new HpackEncoder(1024);
        HeaderMap headers = new HeaderMap();
        // Add several headers with long values to increase encoded size
        headers.put(new HttpString("x-custom-one"), "value-one-value-one-value-one");
        headers.put(new HttpString("x-custom-two"), "value-two-value-two-value-two");

        // Intentionally small buffer to trigger overflow on first encoded header
        ByteBuffer tinyBuffer = ByteBuffer.allocate(16);

        HpackEncoder.State result = encoder.encode(headers, tinyBuffer);

        // We expect an overflow state because the buffer isn't enough to hold the first encoded piece
        assertEquals(HpackEncoder.State.OVERFLOW, result, "Expected OVERFLOW when target buffer is too small");
        // After overflow, overflowData must be populated
        // Continue with a larger buffer to complete encoding
        ByteBuffer continuation = ByteBuffer.allocate(1024);
        HpackEncoder.State result2 = encoder.encode(headers, continuation);
        assertEquals(HpackEncoder.State.COMPLETE, result2, "Expected COMPLETE after continuing with a larger buffer");
        assertTrue(continuation.position() > 0, "Continuation buffer should contain encoded data");
    }

    /**
     * Continuation with mismatched HeaderMap should throw IllegalStateException.
     * This tests the invariant that continuation after an overflow must use the same header map instance.
     */
    @Test
    public void testOverflowContinuationWithDifferentHeaderMapThrows() {
        HpackEncoder encoder = new HpackEncoder(512);
        HeaderMap headersA = new HeaderMap();
        headersA.put(Headers.CONTENT_LENGTH, "1234");

        HeaderMap headersB = new HeaderMap();
        headersB.put(Headers.CONTENT_LENGTH, "1234");

        ByteBuffer small = ByteBuffer.allocate(8);
        // First call with headersA should cause overflow
        encoder.encode(headersA, small);

        // Now attempt continuation with a different header map instance; should throw
        assertThrows(IllegalStateException.class, () -> encoder.encode(headersB, ByteBuffer.allocate(256)),
                "Expected IllegalStateException when continuing with a different HeaderMap instance");
    }

