    // Minimal stubs to construct an Http2Channel and related parser objects.
    private static class DummyHttp2Channel extends Http2Channel {

        public DummyHttp2Channel(StreamConnection connectedStreamChannel, String protocol, ByteBufferPool bufferPool, PooledByteBuffer data, boolean clientSide, boolean fromUpgrade, OptionMap settings) {
