        }

        // Expose a method that delegates to protected createChannelImpl
        public AbstractHttp2StreamSourceChannel invokeCreateChannelImpl(FrameHeaderData headerData, PooledByteBuffer frameData) throws IOException {
            return super.createChannelImpl(headerData, frameData);
        }

        // Expose internal state for tests if needed
        public boolean isServer() {
            // basic heuristic: clientSide flag is true in constructor; if needed override via subclass
            return false;
        }

        // Access to internal fields is not generally possible; tests focus on behavior of createChannelImpl.
    }

    private ByteBufferPool bufferPool;
    private StreamConnection dummyConnection;
    private PooledByteBuffer dummyFrameData;

    @BeforeEach
    public void setup() {
        bufferPool = mock(ByteBufferPool.class);
        dummyConnection = mock(StreamConnection.class);
        // Minimal dummy frame data; we won't rely on remaining() in tests
        dummyFrameData = mock(PooledByteBuffer.class);
    }

    @Test
    public void testDataFrameResultsInGoAwayAndNullChannel() throws Exception {
        // Arrange: create a frame header parser for a DATA frame which should cause a protocol error
        Http2Channel channel = new DummyHttp2Channel(dummyConnection, null, bufferPool, dummyFrameData, true, false, org.xnio.OptionMap.EMPTY);
        // Build a Http2FrameHeaderParser with a dummy data for frame length and stream
        Http2FrameHeaderParser headerParser = new Http2FrameHeaderParser(channel, null);
        // simulate a DATA frame
        headerParser.type = Http2Channel.FRAME_TYPE_DATA;
        headerParser.streamId = 1;
        headerParser.flags = 0;
        headerParser.length = 0;

        // The Http2FrameHeaderParser is both FrameHeaderData and carries the data
        // Use a tiny Http2DataFrameParser to attach to headerParser to satisfy cast to Http2FrameHeaderParser
        // But for test simplicity, reuse headerParser as headerData
        PooledByteBuffer frameData = mock(PooledByteBuffer.class);

        // Act
        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(headerParser, frameData);

        // Assert: For DATA frame, should drop and return null after sending GOAWAY
        assertNull(result, "DATA frames should not create a channel and should drop with protocol error (return null).");
        // We cannot easily verify GOAWAY was sent in this synthetic test without deeper internals.
        // Ensure no exception was thrown and the method returned null as per spec for DATA frames.
    }

