    public void testHeadersFrameCreatesChannelAndUpdatesState() throws Exception {
        // Arrange a scenario where a HEADERS frame arrives for a new idle stream.
        Http2Channel channel = new DummyHttp2Channel(dummyConnection, null, bufferPool, dummyFrameData, true, false, org.xnio.OptionMap.EMPTY);
        // Prepare a HEADERS frame parser
        Http2FrameHeaderParser headerParser = new Http2FrameHeaderParser(channel, null);
