        headerParser.parser = headersParser;

        // No existing streams
        PooledByteBuffer frameData = mock(PooledByteBuffer.class);

        // Act
        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(headerParser, frameData);

        // Assert: a Http2StreamSourceChannel should be created
        assertNotNull(result, "HEADERS frame for a new idle stream should create a Http2StreamSourceChannel.");
    }

    @Test
    public void testGoAwayOnPushPromiseFromServerViolation() throws Exception {
        // Arrange: simulate a PUSH_PROMISE frame where server receives a push promise (server should error)
        Http2Channel channel = new DummyHttp2Channel(dummyConnection, null, bufferPool, dummyFrameData, false, false, org.xnio.OptionMap.EMPTY); // server side
        Http2FrameHeaderParser headerParser = new Http2FrameHeaderParser(channel, null);
        headerParser.type = Http2Channel.FRAME_TYPE_PUSH_PROMISE;

