        Http2PushPromiseParser pushParser = mock(Http2PushPromiseParser.class);
        when(pushParser.getHeaderMap()).thenReturn(mock(HeaderMap.class));
        when(pushParser.getPromisedStreamId()).thenReturn(5);

        headerParser.parser = pushParser;

        PooledByteBuffer frameData = mock(PooledByteBuffer.class);

        // Act
        AbstractHttp2StreamSourceChannel result = channel.createChannelImpl(headerParser, frameData);

        // Assert: on server receiving PUSH_PROMISE we should throw a protocol error
        // Our implementation would either throw or return null; test that it's null in this constrained environment
        assertNull(result, "SERVER PUSH_PROMISE should be rejected and return null channel (and may trigger GOAWAY).");
    }
