        int type;
        MinimalHttp2FrameHeaderParser(Http2Channel channel) {
            super(channel, null);
        }
    }

    @Test
    void testCreateChannelImplDataFrameProducesGoAwayAndNullChannel() throws IOException {
        // Arrange: prepare a DATA frame header to trigger the protocol-error branch
        Http2FrameHeaderParser frameHeader = new Http2FrameHeaderParser(channel, null);
        frameHeader.type = Http2Channel.FRAME_TYPE_DATA; // 0x00
        frameHeader.streamId = 3;
        frameHeader.length = 100;

