package io.undertow.protocols.http2;

import io.undertow.server.protocol.framed.SendFrameHeader;
import io.undertow.util.HeaderMap;
import org.junit.jupiter.api.Test;

import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

/**
 * Tests for Http2DataStreamSinkChannel.createFrameHeaderImpl behavior via its public helper.
 * Focuses on a scenario where the flow-control window is exhausted (fcWindow == 0),
 * ensuring the header is constructed with the remaining data and no actual header/buffer payload is produced.
 */
public class Http2DataStreamSinkChannelCreateFrameHeaderImplTests {

    @Test
    public void testCreateFrameHeaderWhenFlowControlExhausted() {
        // Arrange
        Http2Channel mockChannel = mock(Http2Channel.class);
        // No padding
        when(mockChannel.getPaddingBytes()).thenReturn(0);
        // Simulate exhausted flow control: fcWindow will be 0
        when(mockChannel.grabFlowControlBytes(anyInt())).thenReturn(0);

        // Provide a small data buffer with some remaining bytes.
        ByteBuffer dataBuffer = ByteBuffer.allocate(5);

        // Create a testable subclass that exposes the protected
        // getBuffer() while injecting our own ByteBuffer for testing.
        TestableHttp2DataStreamSinkChannel channel =
                new TestableHttp2DataStreamSinkChannel(mockChannel, 1, dataBuffer);

        // Act
        SendFrameHeader header = channel.generateSendFrameHeader();

        // Assert
        assertNotNull(header, "Header should not be null");
        assertEquals(5, header.getRemainingInBuffer(), "Remaining buffer reported should equal data buffer size");
        assertNull(header.getByteBuffer(), "In fcWindow==0 path, no header frame buffer should be created");
        assertEquals(false, header.isAnotherFrameRequired(), "No additional frame should be required in this path");

        // Ensure the original data buffer was not consumed or altered
        assertEquals(0, dataBuffer.position(), "Input data buffer position should remain unchanged");
        assertEquals(5, dataBuffer.remaining(), "Input data buffer remaining should remain unchanged");
    }

    // Helper subclass to allow overriding getBuffer for test control
    static class TestableHttp2DataStreamSinkChannel extends Http2DataStreamSinkChannel {
        private final ByteBuffer testBuffer;

        TestableHttp2DataStreamSinkChannel(Http2Channel channel, int streamId, ByteBuffer buf) {
            super(channel, streamId, Http2Channel.FRAME_TYPE_HEADERS);
            this.testBuffer = buf;
        }

        @Override
        public ByteBuffer getBuffer() {
            return testBuffer;
        }
    }
}

