import io.undertow.util.Headers;

public class HostHeaderHandlerHandleRequestTests {

    @Test
    public void testNoHostHeaderTerminatesWithNoHostHeaderMessage() throws Exception {
        HttpServerExchange exchange = new HttpServerExchange((ServerConnection) null);

        AtomicBoolean nextCalled = new AtomicBoolean(false);
        HttpHandler next = new HttpHandler() {
            @Override
            public void handleRequest(HttpServerExchange exch) throws Exception {
                nextCalled.set(true);
            }
        };

        HostHeaderHandler handler = new HostHeaderHandler(next);
        handler.handleRequest(exchange);

        assertEquals(400, exchange.getStatusCode(), "Status should be 400 when Host header is missing");
        assertEquals(HostHeaderHandler.STATUS_NO_HOST_HEADER, exchange.getReasonPhrase(), "Reason phrase should indicate missing Host header");
        assertFalse(nextCalled.get(), "Next handler should not be called when Host header is missing");
    }

    @Test
    public void testMultipleHostHeadersTerminates() throws Exception {
        HttpServerExchange exchange = new HttpServerExchange((ServerConnection) null);
        exchange.getRequestHeaders().add(Headers.HOST, "example.com");
        exchange.getRequestHeaders().add(Headers.HOST, "duplicate.example.com");

        AtomicBoolean nextCalled = new AtomicBoolean(false);
