class HostHeaderHandlerHandleRequestTests {

    // A minimal next handler that records whether it was invoked
    static class RecordingNext implements HttpHandler {
        boolean invoked = false;
        @Override
        public void handleRequest(HttpServerExchange exchange) throws Exception {
            invoked = true;
        }
    }

