    @BeforeEach
    void setup() {
        // The HostHeaderHandler delegates to a next handler; for tests we will wrap a simple RecordingNext
        RecordingNext next = new RecordingNext();
        handler = new HostHeaderHandler(next);
    }

    // Helper to create a minimal HttpServerExchange with desired protocol and request headers
    private HttpServerExchange newExchangeForTest(String protocol, HeaderValues hostHeaderValue) {
        HeaderMap requestHeaders = new HeaderMap();
        if (hostHeaderValue != null) {
            requestHeaders.put(Headers.HOST, hostHeaderValue);
        }
        HeaderMap responseHeaders = new HeaderMap();
        FakeServerConnection fake = new FakeServerConnection();
        HttpServerExchange exchange = new HttpServerExchange(fake, requestHeaders, responseHeaders, 0);
        exchange.setProtocol(new HttpString(protocol));
        // By default host is not included in request URI, tests can adjust if needed
        exchange.setRequestURI("/path");
        exchange.setRequestScheme("http");
        return exchange;
    }

    @Test
    void testNoHostHeaderTerminatesWithBadRequest() throws Exception {
        // No Host header should terminate with No Host Header
        HttpServerExchange exchange = newExchangeForTest(Protocols.HTTP_1_1.toString(), null);
        // Ensure HOST header missing
        hostHeaderAbsent(exchange);
        handler.handleRequest(exchange);
        // Since Host header is missing, the exchange should be terminated with BAD_REQUEST
        assertEquals(StatusCodes.BAD_REQUEST, exchange.getStatusCode());
        assertEquals(HostHeaderHandler.STATUS_NO_HOST_HEADER, exchange.getReasonPhrase());
        // Ensure next was not invoked
        assertFalse(((RecordingNext) handler.next).invoked);
    }

    @Test
    void testMultipleHostHeadersTerminatesWithTooMany() throws Exception {
        // More than one Host header value should terminate with Too Many Host Headers
        HttpServerExchange exchange = newExchangeForTest(Protocols.HTTP_1_1.toString(), null);
        // Put two host headers
        exchange.getRequestHeaders().put(Headers.HOST, new HeaderValues("example.com", "example.org"));
        exchange.setProtocol(new HttpString(Protocols.HTTP_1_1));
        handler.handleRequest(exchange);
        assertEquals(StatusCodes.BAD_REQUEST, exchange.getStatusCode());
        assertEquals(HostHeaderHandler.STATUS_TOO_MANY_HOST_HEADERS, exchange.getReasonPhrase());
