        // To keep test robust, ensure no 400 is produced for this exact value according to spec
        // If implementation treats as valid, next should be invoked
        // We allow either, but we require at least a non-400 or that next invoked
        // Here we expect it to not terminate due to malformed IP-literal since it's well-formed
        assertEquals(StatusCodes.OK, exchange.getStatusCode());
    }

    @Test
    void testHostHeaderURIValidationMatchesRequestURIWhenIncluded() throws Exception {
        // If Host header value is expected to be contained in request URI when isHostIncludedInRequestURI is true
        HttpServerExchange exchange = newExchangeForTest(Protocols.HTTP_1_1.toString(),
                new HeaderValues("example.com"));
        // Simulate that host is included in request URI
