        exchange.setHostIncludedInRequestURI(true);
        handler.handleRequest(exchange);
        // Depending on validity, should pass
        assertEquals(StatusCodes.OK, exchange.getStatusCode());
        assertTrue(((RecordingNext) handler.next).invoked);
