import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class PredicatedHandlersParserTokenizeTests {

    @Test
    void tokenizeEmptyStringProducesEmptyDeque() {
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize("");
        assertTrue(tokens.isEmpty(), "Expected empty token deque for empty input");
    }

    @Test
    void tokenizeSimpleTokensSeparatedBySpacesHaveCorrectContentAndPositions() {
        String input = "a b c";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);
        List<PredicatedHandlersParser.Token> list = new ArrayList<>(tokens);

        assertEquals(3, list.size(), "Expected three tokens");
        assertEquals("a", list.get(0).getToken());
        // position is the index of the space that ends the token
        assertEquals(1, list.get(0).getPosition());

        assertEquals("b", list.get(1).getToken());
        assertEquals(3, list.get(1).getPosition());

        assertEquals("c", list.get(2).getToken());
        assertEquals(input.length(), list.get(2).getPosition());
    }

    @Test
    void tokenizeQuotedContentProducesSingleTokenWithEscapedContent() {
        // The content inside quotes with an escaped quote should be preserved as a literal quote inside the token
        String input = "\"a\\\"b\"";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);
        List<PredicatedHandlersParser.Token> list = new ArrayList<>(tokens);

        assertEquals(1, list.size(), "Expected one token inside quotes");
        PredicatedHandlersParser.Token t = list.get(0);
        assertEquals("a\"b", t.getToken()); // content should include the escaped quote resolved to a literal quote
        assertEquals(input.length(), t.getPosition());
    }

    @Test
    void tokenizeBracketsAndParenthesesAreTokenizedSeparatelyWithProperPositions() {
        String input = "a(b)";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);
        List<PredicatedHandlersParser.Token> list = new ArrayList<>(tokens);

        // Expected tokens based on the implementation behavior:
        // "a" at position of first space/term, then "(" at same position, etc.
        assertEquals(4, list.size(), "Expected four tokens for input with a single pair of parentheses");
        assertEquals("a", list.get(0).getToken());
        assertEquals(1, list.get(0).getPosition());

        assertEquals("(", list.get(1).getToken());
        assertEquals(1, list.get(1).getPosition());

        assertEquals("b", list.get(2).getToken());
        assertEquals(3, list.get(2).getPosition());

        assertEquals(")", list.get(3).getToken());
        assertEquals(3, list.get(3).getPosition());
    }

}

