package io.undertow.server.handlers.builder;

import org.junit.jupiter.api.Test;

import java.util.Deque;

import static org.junit.jupiter.api.Assertions.*;

public class PredicatedHandlersParserTokenizeTests {

    @Test
    void emptyInputProducesEmptyDeque() {
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize("");
        assertTrue(tokens.isEmpty(), "Expected empty token deque for empty input");
    }

    @Test
    void arrowTokenBetweenAAndB() {
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize("A->B");
        assertEquals(3, tokens.size(), "Expected three tokens: A, ->, B");

        PredicatedHandlersParser.Token t1 = tokens.pollFirst();
        assertEquals("A", t1.getToken());
        assertEquals(0, t1.getPosition());

        PredicatedHandlersParser.Token t2 = tokens.pollFirst();
        assertEquals("->", t2.getToken());
        assertEquals(2, t2.getPosition());

        PredicatedHandlersParser.Token t3 = tokens.pollFirst();
        assertEquals("B", t3.getToken());
        assertEquals(3, t3.getPosition());
    }

    @Test
    void stringLiteralContentIsTokenWithoutQuotes() {
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize("func(\"x\")");
        assertEquals(4, tokens.size(), "Expected tokens: func, (, x, )");

        PredicatedHandlersParser.Token t1 = tokens.pollFirst();
        assertEquals("func", t1.getToken());
        assertEquals(0, t1.getPosition());

        PredicatedHandlersParser.Token t2 = tokens.pollFirst();
        assertEquals("(", t2.getToken());
        assertEquals(4, t2.getPosition());

        PredicatedHandlersParser.Token t3 = tokens.pollFirst();
        assertEquals("x", t3.getToken());
        assertEquals(7, t3.getPosition());

        PredicatedHandlersParser.Token t4 = tokens.pollFirst();
        assertEquals(")", t4.getToken());
        assertEquals(8, t4.getPosition());
    }

    @Test
    void lineCommentsAreIgnoredAtLineStart() {
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize("#comment\\nnext");
        // The comment line should be skipped; only "next" should be tokenized
        assertEquals(1, tokens.size(), "Expected a single token after skipping comment line");
        PredicatedHandlersParser.Token t = tokens.pollFirst();
        assertEquals("next", t.getToken());
        assertEquals(9, t.getPosition() == 0 ? 0 : t.getPosition(), "Position should be the token's actual position");
        assertTrue(tokens.isEmpty(), "No more tokens should remain");
    }

    @Test
    void newlineTokenInsertedBetweenTokens() {
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize("a\nb");
        assertEquals(3, tokens.size(), "Expected tokens: a, newline, b");

        PredicatedHandlersParser.Token t1 = tokens.pollFirst();
        assertEquals("a", t1.getToken());
        assertEquals(0, t1.getPosition());

        PredicatedHandlersParser.Token t2 = tokens.pollFirst();
        assertEquals("\n", t2.getToken());
        assertEquals(1, t2.getPosition());

        PredicatedHandlersParser.Token t3 = tokens.pollFirst();
        assertEquals("b", t3.getToken());
        // The position for the final token uses the string length; with "a\nb" length is 3
        assertEquals(3, t3.getPosition());
    }
}

