import java.util.stream.Collectors;

import static org.junit.jupiter.api.Assertions.*;

public class PredicatedHandlersParserTokenizeTests {

    @Test
    public void testArrowTokenization() {
        String input = "a->b";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);

        List<String> tokenStrings = tokens.stream()
                .map(PredicatedHandlersParser.Token::getToken)
                .collect(Collectors.toList());

        List<Integer> positions = tokens.stream()
                .map(PredicatedHandlersParser.Token::getPosition)
                .collect(Collectors.toList());

        assertEquals(List.of("a", "->", "b"), tokenStrings, "Token sequence should be 'a', '->', 'b'");
        assertEquals(List.of(2, 2, 4), positions, "Token positions for 'a', '->', 'b' should be 2, 2, 4 respectively");
    }

    @Test
    public void testStringLiteralToken() {
        String input = "\"hello\"";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);

        List<String> tokenStrings = tokens.stream()
                .map(PredicatedHandlersParser.Token::getToken)
                .collect(Collectors.toList());

        List<Integer> positions = tokens.stream()
                .map(PredicatedHandlersParser.Token::getPosition)
                .collect(Collectors.toList());

        assertEquals(List.of("hello"), tokenStrings, "String literal should yield a single token: 'hello'");
        assertEquals(List.of(6), positions, "Position of string token should be the index of closing quote (6)");
    }

    @Test
    public void testLineCommentAndNewlineToken() {
        String input = "# skip this line\nabc";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);

        List<String> tokenStrings = tokens.stream()
                .map(PredicatedHandlersParser.Token::getToken)
                .collect(Collectors.toList());

        List<Integer> positions = tokens.stream()
                .map(PredicatedHandlersParser.Token::getPosition)
                .collect(Collectors.toList());

        // The line comment is skipped; a newline token is emitted, followed by the actual token "abc".
        // Newline is at index of '\n' (16); final "abc" token has position equal to string.length() (20).
        assertEquals(List.of("\n", "abc"), tokenStrings, "Should yield a newline token followed by 'abc'");
        assertEquals(List.of(16, 20), positions, "Newline position should be 16 and 'abc' token position should be 20");
    }

    @Test
    public void testBraceTokens() {
        String input = "{a}";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);

        List<String> tokenStrings = tokens.stream()
                .map(PredicatedHandlersParser.Token::getToken)
                .collect(Collectors.toList());

        List<Integer> positions = tokens.stream()
                .map(PredicatedHandlersParser.Token::getPosition)
                .collect(Collectors.toList());

        // Expect tokens for open brace, inner content, and close brace with their respective positions.
        assertEquals(List.of("{", "a", "}"), tokenStrings, "Brace content should yield '{', 'a', '}' tokens");
        assertEquals(List.of(0, 2, 2), positions, "Brace tokens should have positions 0, 2, 2 respectively");
    }

    @Test
    public void testSemicolonSeparatedTokens() {
        String input = "a; b";
        Deque<PredicatedHandlersParser.Token> tokens = PredicatedHandlersParser.tokenize(input);

        List<String> tokenStrings = tokens.stream()
                .map(PredicatedHandlersParser.Token::getToken)
                .collect(Collectors.toList());

        List<Integer> positions = tokens.stream()
                .map(PredicatedHandlersParser.Token::getPosition)
                .collect(Collectors.toList());

        // Expect tokens for 'a', ';', and 'b' with appropriate positions.
        assertEquals(List.of("a", ";", "b"), tokenStrings, "Tokens should be 'a', ';', 'b'");
        assertEquals(List.of(1, 1, 4), positions, "Positions should be 1 for 'a', 1 for ';', and 4 for 'b'");
    }
}

