package io.undertow.server.protocol.ajp;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.ByteBuffer;

import org.junit.jupiter.api.Test;

import io.undertow.server.HttpServerExchange;
import io.undertow.server.protocol.ajp.AjpRequestParser;
import io.undertow.server.protocol.ajp.AjpRequestParseState;
import io.undertow.util.BadRequestException;
import io.undertow.util.HttpString;
import io.undertow.util.Methods;

/**
 * Tests for AjpRequestParser.parse behavior.
 * These tests focus on observable behavior exposed via the public API.
 */
public class AjpRequestParserParseTests {

    @Test
    public void testWrongMagicNumberThrowsBadRequest() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 100, 100, true, true);

        // Magic number is 0x5678 (wrong)
        ByteBuffer buf = ByteBuffer.allocate(2);
        buf.putShort((short) 0x5678);
        buf.flip();

        AjpRequestParseState state = new AjpRequestParseState();
        // initialize to BEGIN
        state.state = AjpRequestParseState.BEGIN;

        HttpServerExchange exchange = new HttpServerExchange((io.undertow.server.ServerConnection) null);

        assertThrows(BadRequestException.class, () -> {
            parser.parse(buf, state, exchange);
        });
    }

    @Test
    public void testParseSetsMethodWhenPresent() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 100, 100, true, true);

        // Sequence:
        // 2 bytes magic (0x1234)
        // 2 bytes data size (0)
        // 1 byte prefix (2)
        // 1 byte method (2 -> GET)
        ByteBuffer buf = ByteBuffer.allocate(6);
        buf.putShort((short) 0x1234); // magic
        buf.putShort((short) 0);      // data size
        buf.put((byte) 2);            // prefix code
        buf.put((byte) 2);            // method (GET)
        buf.flip();

        AjpRequestParseState state = new AjpRequestParseState();
        state.state = AjpRequestParseState.BEGIN;

        HttpServerExchange exchange = new HttpServerExchange((io.undertow.server.ServerConnection) null);

        parser.parse(buf, state, exchange);

        // Expect the GET method to be set in the exchange
        HttpString expected = Methods.GET;
        assertEquals(expected, exchange.getRequestMethod());
    }

}

