import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import java.nio.ByteBuffer;

import org.junit.jupiter.api.Test;

import io.undertow.server.HttpServerExchange;
import io.undertow.util.HttpString;
import io.undertow.server.protocol.ajp.AjpRequestParseState;
import io.undertow.server.protocol.ajp.AjpRequestParser;
import io.undertow.util.BadRequestException;

/**
 * Executable unit tests for AjpRequestParser.parse, focusing on state transitions and observable effects
 * on the HttpServerExchange.
 */
public class AjpRequestParserParseTests {

    @Test
    void testMagicNumberWrongThrowsBadRequest() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 100, 100, true, true);
        AjpRequestParseState state = new AjpRequestParseState();
        state.state = AjpRequestParseState.BEGIN;

        // Wrong magic number: 0x1235
        ByteBuffer buf = ByteBuffer.wrap(new byte[] { (byte) 0x12, (byte) 0x35 });

        HttpServerExchange exchange = mock(HttpServerExchange.class);

        assertThrows(BadRequestException.class, () -> {
            parser.parse(buf, state, exchange);
        });
    }

    @Test
    void testIncompleteAfterMagicKeepsReadingDataSize() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 100, 100, true, true);
        AjpRequestParseState state = new AjpRequestParseState();
        state.state = AjpRequestParseState.BEGIN;

        // Magic number correct, but no dataSize bytes beyond it
        ByteBuffer buf = ByteBuffer.wrap(new byte[] { (byte) 0x12, (byte) 0x34 });

        HttpServerExchange exchange = mock(HttpServerExchange.class);

        parser.parse(buf, state, exchange);

        assertEquals(AjpRequestParseState.READING_DATA_SIZE, state.state,
                "After partial processing the state should be READING_DATA_SIZE");
    }

    @Test
    void testPrefixCodeAdvancesToReadingMethod() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 100, 100, true, true);
        AjpRequestParseState state = new AjpRequestParseState();
        state.state = AjpRequestParseState.BEGIN;

        // Magic (0x1234) + DataSize (0x0001) + Prefix (0x02) incomplete data for method
        ByteBuffer buf = ByteBuffer.wrap(new byte[] { (byte)0x12, (byte)0x34, 0x00, 0x01, 0x02 });

        HttpServerExchange exchange = mock(HttpServerExchange.class);

        parser.parse(buf, state, exchange);

        assertEquals(AjpRequestParseState.READING_METHOD, state.state,
                "When prefix code is 2 and no method byte available, state should be READING_METHOD on next cycle or this cycle.");
    }

    @Test
    void testMethodInvocationLeadsToExchangeMethodSet() throws Exception {
        AjpRequestParser parser = new AjpRequestParser("UTF-8", true, 100, 100, true, true);
        AjpRequestParseState state = new AjpRequestParseState();
        state.state = AjpRequestParseState.BEGIN;

        // Magic (0x1234) + DataSize (0x0001) + Prefix (0x02) + Method (0x01)
        // This should cause exchange.setRequestMethod to be called with a valid HttpString from HTTP_METHODS[1]
        ByteBuffer buf = ByteBuffer.wrap(new byte[] { (byte)0x12, (byte)0x34, 0x00, 0x01, 0x02, 0x01 });

        HttpServerExchange exchange = mock(HttpServerExchange.class);

        parser.parse(buf, state, exchange);

        verify(exchange).setRequestMethod(any(HttpString.class));
    }

}

